{#- Code generated by packages/kit-compose/src/server-organisms.ts from packages/compose-gen/specs (compose-gen organism emitters on kit-compose). DO NOT EDIT.
    Source: packages/compose-gen/specs/organisms/nav-links.json
    The links of a top bar in a row; the current one carries aria-current. side: all, or the first or second half of the list.
    Props (p): links, current, side. -#}
{%- set v_links = (p.links ?? null) -%}
{%- set v_current = (p.current ?? '') -%}
{%- set v_side = (p.side ?? 'all') -%}
{%- set v_count = og_len(v_links) -%}
{%- if og_t(og_gt(og_len(v_links), 0)) %}
  {%- set c_2 -%}
    {%- for v_l in og_l(v_links) %}
      {%- set v_i = loop.index0 -%}
      {%- if og_t(og_or([og_eq(v_side, 'all'), og_eq(og_lt(og_mul(v_i, 2), v_count), og_eq(v_side, 'left'))])) %}
        {%- set c_1 -%}
          {{ og_text(og_get(v_l, ['name'])) }}
        {%- endset -%}
        {{ include('blocks/menu-entry.html.twig', {'p': {'href': og_get(v_l, ['href']), 'className': og_cnv(['text-sm']), 'current': og_eq(og_get(v_l, ['id']), v_current), 'testid': 'nav-link'}, 'children': og_markup(c_1)}, with_context = false) }}
      {%- endif %}
    {%- endfor %}
  {%- endset -%}
  {{ include('compose/Group.html.twig', {'gap': '4', 'align': 'center', 'class': 'flex-wrap', 'attrs': og_attrs(['data-slot', 'nav-links']), 'children': c_2}, with_context = false) }}
{%- endif %}
